 b=p.chromium.launch(headless=False,args=ARGS,env=env,executable_path='/usr/bin/chromium');page=b.new_page(viewport={'width':1100,'height':700});page.goto('http://127.0.0.1:8765/skill/?renderer=webgl2');page.wait_for_function('window.__lingSkill && window.__lingSkill.ready',timeout=90000);page.keyboard.down('Shift');page.keyboard.down('w');page.wait_for_function('Math.hypot(window.__lingSkill.position[0],window.__lingSkill.position[2])>9.25',timeout=120000);page.keyboard.up('w');page.keyboard.up('Shift');page.locator('#cast').click();page.wait_for_function('window.__lingSkill.time>1.8',timeout=40000);a=page.evaluate('window.__lingSkill');assert math.hypot(a['position'][0],a['position'][2])<=9.501,a['position'];page.locator('#cast3').click();page.wait_for_function('window.__lingSkill.dragonVisible && window.__lingSkill.time>1.5',timeout=40000);u=page.evaluate('window.__lingSkill');assert math.hypot(u['position'][0],u['position'][2])+3.5<17.1 and not u['errors'];page.screenshot(path=str(out/'boundary-ultimate.png'));(out/'boundary.json').write_text(json.dumps({'status':'PASS_SOFTWARE_ONLY','first_skill_actor':a['position'],'ultimate_actor':u['position'],'platform_radius':17,'ultimate_ground_effect_radius':3.5,'errors':u['errors']},indent=2));print('PASS boundary, first skill clamp and ultimate ground coverage',flush=True);b.close()
